#!/usr/bin/env python3
"""Pin cached raw source and append one finite review without rewriting old data bytes."""
import argparse,hashlib,json,pathlib,xml.etree.ElementTree as E
p=argparse.ArgumentParser();p.add_argument('--xml',required=True);p.add_argument('--data',required=True);p.add_argument('--out',required=True);p.add_argument('--apply',action='store_true');a=p.parse_args();raw=pathlib.Path(a.xml).read_bytes();r=E.fromstring(raw);ns={int(n.attrib['id']):n for n in r.findall('node')};ws={int(w.attrib['id']):w for w in r.findall('way')};target=pathlib.Path(a.data);old=target.read_bytes();d=json.loads(old);q=d['proj'];tags=lambda el:{x.attrib['k']:x.attrib['v'] for x in el.findall('tag')}
def snapshot(id):
 w=ws[int(id[1:])];ids=[int(n.attrib['ref']) for n in w.findall('nd')];ll=[[float(ns[n].attrib['lat']),float(ns[n].attrib['lon'])] for n in ids];xy=[[(lo-q['lon0'])*q['mPerLon']*q.get('scale',1),-(la-q['lat0'])*q['mPerLat']*q.get('scale',1)] for la,lo in ll]
 return {'sourceId':id,'nodeIds':ids,'wgs84':ll,'projected':xy,'tags':tags(w),'nodeTags':{str(n):tags(ns[n]) for n in ids if tags(ns[n])}}
ids=['w79870041','w668563018','w668563017','w1478497247','w982816382'];ways=[snapshot(i) for i in ids];roof=snapshot('w670595374');roof['projected']=roof['projected'][:-1];roof['closedSourceNodeOrderRetained']=True
record={'schemaVersion':1,'id':'unirii-mol-coposu-source-canopy-cover','classification':'reviewed-source-fuel-canopy-covered-road','sourceRoadId':'w79870041','sourceCanopyId':'w670595374','sourceXmlSha256':hashlib.sha256(raw).hexdigest(),'evidence':['https://www.openstreetmap.org/way/79870041','https://www.openstreetmap.org/way/670595374','https://www.openstreetmap.org/way/668563018','https://www.openstreetmap.org/way/668563017','https://www.openstreetmap.org/way/1478497247','https://www.openstreetmap.org/way/982816382'],'sourceWays':ways,'sourceCanopy':roof,'groundJoins':[{'portalNodeId':6260825651,'anchorRoadId':'w982816382','anchorNodeId':9088160162,'ways':[['w668563018',1]]},{'portalNodeId':13563618634,'anchorRoadId':'w982816382','anchorNodeId':9088160161,'ways':[['w668563017',-1],['w1478497247',-1]]}],'model':{'estimated':True,'floorY':0,'basis':'Reviewed literal open MOL canopy and exact same-source-node connections to ordinary Coposu surface carriageway. Raw layer−1 is relative ordering beneath layer1 canopy, not6m underground elevation. Existing4.8m canopy underside/5.2m top remain model estimates.'}}
for w in ways:
 rows=[s for s in d['roadSourceGeometry'].values() if s['sourceId']==w['sourceId']]
 assert rows and all(all(s[k]==w[k] for k in ['sourceId','nodeIds','tags','projected']) for s in rows),w['sourceId']
out=pathlib.Path(a.out);out.mkdir(parents=True,exist_ok=True);(out/'canopy-review.json').write_text(json.dumps(record,indent=2)+'\n')
ledger={'sourceXmlFile':str(pathlib.Path(a.xml)),'sourceXmlBytes':len(raw),'sourceXmlSha256':hashlib.sha256(raw).hexdigest(),'dataBeforeSha256':hashlib.sha256(old).hexdigest(),'policy':'Only one appended reviewedCoveredRoads field; all preexisting bytes/arrays/dates/footprints/source tags retained. No reference image. Existing reviewed canopy dimensions are not measurements.'}
if a.apply:
 assert 'reviewedCoveredRoads' not in d
 i=old.rfind(b'}');add=b',"reviewedCoveredRoads":'+json.dumps([record],ensure_ascii=False,separators=(',',':')).encode();new=old[:i]+add+old[i:];newd=json.loads(new);assert all(newd[k]==v for k,v in d.items());assert new[:i]==old[:i];target.write_bytes(new);ledger.update({'dataAfterSha256':hashlib.sha256(new).hexdigest(),'allPreexistingFieldsIdentical':True,'allPreexistingBytesBeforeFinalBraceIdentical':True,'appendedBytes':len(add)})
(out/'metadata-write.json').write_text(json.dumps(ledger,indent=2)+'\n');print(json.dumps(ledger))
